from hermes_tools import search_files, read_file
root='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-seq0/frozen/held-out/play/users/u022/system/state/hermes/cache/delegation/live'
for p in ['*']:
 r=search_files(p,target='files',path=root,limit=100)
 for f in r.get('files',[]):
  if f.endswith('task-0.log') or f.endswith('task-1.log'):
   txt=read_file(f,offset=1,limit=300).get('content','')
   if 'b6a136b2' in txt or '4x4' in txt or '8-masked' in txt:
    print('\nFILE',f,'\n',txt[:5000])

import sqlite3,re
p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-seq0/frozen/held-out/play/users/u022/system/state/hermes/state.db'
c=sqlite3.connect(p)
msg=c.execute("select content from messages where id=593").fetchone()[0]
def get_rows(a,b):
 s=msg.split(a,1)[1].split(b,1)[0]
 return [list(map(int,line.split())) for line in s.strip().splitlines() if line.strip()]
g=get_rows('Demo pair 3 input (30x30):','Demo pair 3 output')
out=get_rows('Demo pair 3 output (9x4):','Same instance.')
print('dims',len(g),set(map(len,g)),len(out),set(map(len,out)))
# check output or D4 transforms matching anywhere
transforms={'identity':out,'hflip':[r[::-1] for r in out],'vflip':out[::-1], 'rot180':[r[::-1] for r in out[::-1]], 'transpose':[list(x) for x in zip(*out)]}
transforms.update({'transpose_hflip':[r[::-1] for r in zip(*out)],'transpose_vflip':[list(x) for x in zip(*out)][::-1], 'transpose_rot180':[r[::-1] for r in zip(*out[::-1])]})
for name,t in transforms.items():
 h,w=len(t),len(t[0]); matches=[]
 for r in range(30-h+1):
  for col in range(30-w+1):
   if all(g[r+i][col:col+w]==t[i] for i in range(h)): matches.append((r+1,col+1))
 print(name, (h,w), matches)
