texts=[r[0] for r in c.execute("select content from messages where session_id=? and role='user' and active=1 order by id",(s,))]
alltxt='\n'.join(texts)
def extract(n, kind, rows):
    m=re.search(rf'Demo pair {n} {kind} \(\d+x\d+\):\n((?:[0-9 ]+\n){{{rows}}})',alltxt)
    if not m: raise ValueError(f'not found {n} {kind}')
    return [[int(x) for x in line.split()] for line in m.group(1).strip().splitlines()]
def transforms(a):
    # D4: 0,90,180,270 turns, plus horizontal reflection then turns
    out=[]
    for refl in (False,True):
        b=[row[:] for row in a]
        if refl: b=[row[::-1] for row in b]
        for k in range(4):
            name=('H-reflect+' if refl else '')+f'rot{k*90}'
            out.append((name,b))
            b=[list(row) for row in zip(*b[::-1])]
    return out
for n,rows,oh,ow in [(2,30,4,5),(3,30,9,4)]:
    grid=extract(n,'input',rows); out=extract(n,'output',oh)
    print('DEMO',n,'dims',len(grid),len(grid[0]),'out',len(out),len(out[0]))
    hits=[]
    for h in range(1,len(grid)+1):
      for w in range(1,len(grid[0])+1):
       if (h,w) not in [(oh,ow),(ow,oh)]: continue
       for r in range(len(grid)-h+1):
        for col in range(len(grid[0])-w+1):
         patch=[row[col:col+w] for row in grid[r:r+h]]
         for name,t in transforms(patch):
          if t==out: hits.append({'origin':[r,col],'source_size':[h,w],'transform':name,'patch':patch})
    print(json.dumps(hits))

