def mat(s): return [[int(x) for x in l.split()] for l in s.strip().splitlines()]
for row in rows:
 for m in pat.finditer(row["content"] or ""):
  k=int(m.group(1)); g=mat(m.group(4)); out=mat(m.group(7)); coords=[(i,j) for i,r in enumerate(g) for j,x in enumerate(r) if x==8]; print("DEMO",k,"inputdim",len(g),len(g[0]),"out",len(out),len(out[0]),"8 bbox",min(i for i,j in coords),max(i for i,j in coords),min(j for i,j in coords),max(j for i,j in coords)); print("OUT",out)
  h,w=len(out),len(out[0]); variants=[("id",lambda a:a),("hflip",lambda a:[r[::-1] for r in a]),("vflip",lambda a:a[::-1]),("rot180",lambda a:[r[::-1] for r in a[::-1]]),("transpose",lambda a:[list(r) for r in zip(*a)])]
  for name,f in variants:
   a=f(out)
   if len(a)==h and len(a[0])==w:
    hits=[]
    for i in range(31-h):
