import sqlite3,re
p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-seq0/frozen/held-out/play/users/u022/system/state/hermes/state.db'
c=sqlite3.connect(p)
s='fc6cdab4-0a6a-4f93-86f0-39d3c32f7910'
t=c.execute('select content from messages where session_id=? and role="user" and content like ? order by id desc limit 1',(s,'%Demo pair 3 input%')).fetchone()[0]
block=t.split('Demo pair 3 input (30x30):\n',1)[1].split('Demo pair 3 output',1)[0]
g=[list(map(int,re.findall(r'\d+',x))) for x in block.strip().splitlines() if x.strip()]
outblock=t.split('Demo pair 3 output (9x4):\n',1)[1].split('\n\nSame instance',1)[0]
o=[list(map(int,re.findall(r'\d+',x))) for x in outblock.strip().splitlines()]
print('grid',len(g),sorted(set(map(len,g))),'out',len(o),sorted(set(map(len,o))))
coords=[(i+1,j+1) for i,r in enumerate(g) for j,v in enumerate(r) if v==8]
print('8 bbox',min(i for i,j in coords),max(i for i,j in coords),min(j for i,j in coords),max(j for i,j in coords),'rows',sorted(set(i for i,j in coords)))
tr={'identity':o,'hflip':[r[::-1] for r in o],'vflip':o[::-1],'rot180':[r[::-1] for r in o[::-1]],'rot90cw':[list(r) for r in zip(*o[::-1])],'rot90ccw':[list(r)[::-1] for r in zip(*o)],'transpose':[list(r) for r in zip(*o)],'anti-transpose':[list(r[::-1]) for r in zip(*o[::-1])]}
for name,patch in tr.items():
 h,w=len(patch),len(patch[0]); hits=[]
 for i in range(31-h):
  for j in range(31-w):
   if [r[j:j+w] for r in g[i:i+h]]==patch: hits.append((i+1,j+1))
 if hits: print(name,hits)
print('output',o)

