def rows(text,n): return [list(map(int,l.split())) for l in text.splitlines()[:n]]
def rot(a): return [list(x) for x in zip(*a[::-1])]
def variants(a):
 out={}
 b=a
 for k in range(4):
  out[f"rot{k}"]=b
  out[f"rot{k}_flipH"]=[r[::-1] for r in b]
  b=rot(b)
 return out
for n,mid,mask in [(1,5,(8,27,4,4)),(2,570,(3,22,4,5)),(3,593,(15,26,6,4))]:
 txt=msg(mid); p=txt.split(f"Demo pair {n} input (30x30):\n",1)[1]; g=rows(p,30)
 x=txt.index(f"Demo pair {n} output (")+len(f"Demo pair {n} output ("); y=txt.index("):",x); h,w=map(int,txt[x:y].split("x")); o=rows(txt[y+2:].strip(),h)
 matches=[]
 for name,a in variants(o).items():
  hh,ww=len(a),len(a[0])
  for r in range(30-hh+1):
   for col in range(30-ww+1):
    if g[r:r+hh] and all(g[r+i][col:col+ww]==a[i] for i in range(hh)): matches.append((name,r+1,col+1))
 print("DEMO",n,"mask",mask,"out",h,w,"exact windows",matches)
t=rows(msg(1).split("Test input (30x30):\n",1)[1],30); q=[(r+1,col+1) for r,row in enumerate(t) for col,v in enumerate(row) if v==8]
print("TEST 8 bbox",min(r for r,col in q),max(r for r,col in q),min(col for r,col in q),max(col for r,col in q),"n",len(q))'",
