 return min(r for r,c in ps),max(r for r,c in ps),min(c for r,c in ps),max(c for r,c in ps)
def find(g,b,margin=2):
 r0,r1,c0,c1=b;h=r1-r0+1;w=c1-c0+1
 # transformations mapping target(local dr,dc) -> source local coords; output transforms source into target: H/V/180
 trans={'id':(lambda x,y:(x,y),h,w),'H':(lambda x,y:(x,w-1-y),h,w),'V':(lambda x,y:(h-1-x,y),h,w),'R':(lambda x,y:(h-1-x,w-1-y),h,w)}
